import { applyCompanyLookupToDraft, formatCepInput, formatCnpjInput, normalizeCnpjInput } from "../../../shared/companyFormRules";
import { BarChart3, Bell, Building2, CalendarClock, ChevronRight, CircleAlert, ClipboardCheck, FileText, LayoutDashboard, LoaderCircle, LogOut, Menu, Plus, Search, Settings, ShieldCheck, Target, Upload, Users, X, Zap } from "lucide-react";
